records.before:
assert.deepEqual(await page.evaluate(() => ['sessionAgents', 'sessionRange', 'sessionSort'].map(id => {
          const group = document.getElementById(id), marker = group.querySelector(':scope > .motion-indicator')?.getBoundingClientRect(), pressed = group.querySelector(':scope > button[aria-pressed="true"]').getBoundingClientRect();
          return Boolean(marker) && Math.abs(marker.left - pressed.left) < 1.5 && Math.abs(marker.top - pressed.top) < 1.5 && Math.abs(marker.width - pressed.width) < 1.5;
        })), [true, true, true])

